  /* ---------- lavabi in gres su misura ---------- */
  function bQ(p){return !!(p.basin&&p.basin.quote)}
  function basinPrice(w){var z=PR.basin.sizes.find(function(x){return x.w===w});return z?z.price:0}
  function basinVasca(id){var v=PR.basin.vasche.find(function(x){return x[0]===id});return v?v[1]:''}
  function basinQuote(p,c){
    if(bQ(p))return{unit:0,lines:[['المغسلة '+(c.dbl?'doppio':'singolo')+' L '+c.w+' سم · السعر حسب عرض السعر',0]],note:'سعر حسب المقاس: نرسل الرسم وعرض السعر'};
    var u=basinPrice(c.w);return{unit:u,lines:[['مغسلة ع '+c.w+' × P '+c.d+' cm · '+basinVasca(c.v),u]],note:PR.basin.ivaNote};
  }
  function priceTxt(p){if(p.type==='basin'&&bQ(p))return 'حسب العرض';return eur.format(fromPrice(p))+(p.type==='tile'?'/m²':'')}
  function basinSum(p,c){return 'L '+c.w+' × P '+c.d+' cm · '+(c.dbl?'مزدوجة · ':'')+basinVasca(c.v)+' · '+c.fin+(c.ton?' ('+c.ton+')':'')}
