      +(p.badge?'<span class="s-badge">'+esc(p.badge)+'</span>':'')+'<span class="s-badge g r2">حسب المقاس</span><span class="s-card-q">'+IC.eye+'اكتشف وخصّص</span></a>'
      +'<span class="s-card-line"><i></i>'+esc(subName(p))+'</span><h3><a href="'+u+'">'+esc(p.name)+'</a></h3><p class="s-desc">'+esc(p.desc)+'</p>'
      +'<span class="s-dim">'+(q?'من 130 إلى 300 سم وأكثر · مفردة أو مزدوجة':'L '+p.basin.w+' سم · عمق حسب الطلب')+'</span>'
      +'<div class="s-price">'+(q?'<span class="s-quote">حسب العرض</span>':eur.format(fromPrice(p))+'<span>بدون ضريبة القيمة المضافة · حسب المقاس</span>')+'</div>'
