    h+='<fieldset class="s-opt"><legend>العمق <small>'+K.depth.min+'–'+K.depth.max+' سم</small></legend><div class="s-dims one"><label>العمق (سم)<input type="number" inputmode="numeric" id="o-d" min="'+K.depth.min+'" max="'+K.depth.max+'"></label></div></fieldset>';
    h+='<fieldset class="s-opt"><legend>الحوض</legend><div class="s-chips" id="o-v">'+K.vasche.map(function(v){return '<button type="button" class="s-chip" data-v="'+v[0]+'">'+esc(v[1])+'</button>'}).join('')+'</div></fieldset>';
    h+='<fieldset class="s-opt"><legend>التشطيب</legend><div class="s-chips" id="o-fin">'+K.finiture.map(function(f){return '<button type="button" class="s-chip" data-v="'+esc(f)+'">'+esc(f)+'</button>'}).join('')+'</div>'
      +'<div class="s-dims one"><label>اللون المفضل <small>اختياري: من <a href="/ar/shop/porcelain-tiles/">كتالوج البلاط لدينا</a> أو حسب وصفكم</small><input type="text" id="o-ton" maxlength="60" placeholder="مثلًا Calacatta Gold، ترافرتين فاتح…"></label></div><p class="s-note">يمكنكم أيضًا إرسال صورة للتشطيب الذي يعجبكم.</p></fieldset>';
