      var g=doorGeom(c);return [op.label+(c.hand==='sx'?' يسار':' يمين'), c.size==='custom'?'الفتحة '+c.vw+'×'+c.vh+' مم، الجدار '+c.wall+' مم (الضلفة '+g.lw+'×'+g.lh+')':c.w+'×'+PR.door.height+' سم، الجدار '+c.wall+' mm', p.line==='laminata'?p.finishes[0]:fmGrezza(c)?'خام للطلاء':'RAL '+(c.ral||'يُحدَّد لاحقًا')].concat(ex).concat(service(c.serv)?[service(c.serv).label]:['بدون نقل وتركيب']).join(' · ');
