      el.addEventListener('keydown',function(e){var s=e.key==='ArrowRight'||e.key==='ArrowUp'?1:e.key==='ArrowLeft'||e.key==='ArrowDown'?-1:0;if(s){e.preventDefault();inp.value=clamp(+inp.value+s*5,+inp.min,+inp.max);upd()}});
